// One-time update: new welcome character + 4 roaming shimeji characters.
// Run by the "Apply mascot update" GitHub Action. It writes files, nothing else.
import fs from 'node:fs';
import path from 'node:path';

const files = {
 "public/mascots/welcome-girl.webp": "",
 "public/mascots/shimeji-pink.webp": "",
 "public/mascots/shimeji-bunny.webp": "",
 "public/mascots/shimeji-glasses.webp": "",
 "public/mascots/shimeji-headphones.webp": "",
 "public/mascots/README.md": "",
 "components/mascots/EdgeMascots.tsx": ""
};

for (const [p, b64] of Object.entries(files)) {
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, Buffer.from(b64, 'base64'));
  console.log('wrote', p);
}

function edit(file, fn) {
  const before = fs.readFileSync(file, 'utf8');
  const after = fn(before);
  if (after === before) throw new Error('Nothing changed in ' + file + ' (already updated or file is different).');
  fs.writeFileSync(file, after);
  console.log('edited', file);
}

// 1) Welcome screen: describe the new character
edit('components/welcome/WelcomeGate.tsx', (s) => {
  if (!s.includes('A friendly anime girl waving hello')) throw new Error('WelcomeGate.tsx text not found');
  return s.replace('A friendly anime girl waving hello', 'A cute girl in a black cat hoodie making peace signs');
});

// 2) Movement: slightly livelier walking and climbing
edit('lib/shimeji.ts', (s) => {
  if (!s.includes('const WALK_SPEED = 38;') || !s.includes('const CLIMB_SPEED = 34;')) throw new Error('shimeji.ts speeds not found');
  return s.replace('const WALK_SPEED = 38;', 'const WALK_SPEED = 54;').replace('const CLIMB_SPEED = 34;', 'const CLIMB_SPEED = 42;');
});

// 3) Styles for the picture characters (added once, at the end of globals.css)
const marker = "/* ===== Roaming picture characters (sprites) ===== */";
const block = Buffer.from("", 'base64').toString('utf8');
const css = fs.readFileSync('app/globals.css', 'utf8');
if (css.includes(marker)) throw new Error('globals.css already has the character styles');
fs.writeFileSync('app/globals.css', css.replace(/\s*$/, '\n\n') + block);
console.log('edited app/globals.css');
